+ * { ingredients: { not_equals: { isHealthy: { equals: false } } } }
+ *
+ * // Simplified MongoDB result, after finding the matching ingredient IDs
+ * { ingredients: { $nin: [unhealthyIngredientID] } }
+ * ```
+ */
